	@Test
	void foldedValuesFilterConstrainsEveryUnionChild() {
		StatementPattern pushdownCapable = new StatementPattern(Var.of("subject"), Var.of("link", LINK, true),
				Var.of("name"));
		Union mixedUnion = new Union(pushdownCapable, values("name", NAME_2));
		Filter foldedValuesFilter = new Filter(values("target", NAME_1),
				new Compare(Var.of("name"), Var.of("target"), Compare.CompareOp.EQ));
		Group group = new Group(new Join(mixedUnion, foldedValuesFilter));
		group.addGroupElement(new GroupElem("count", new Count(Var.of("name"), true)));

		SingleStatementSource source = new SingleStatementSource();
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null, null,
				0L, new EvaluationStatistics(), false);
		QueryEvaluationStep step = LmdbNativeAggregateCompiler.tryCompile(group,
				new QueryEvaluationContext.Minimal((Dataset) null), strategy, source);

		assertThat(step).as("the direct aggregate algebra must compile natively").isNotNull();
		try (CloseableIteration<BindingSet> rows = step.evaluate(EmptyBindingSet.getInstance())) {
			assertThat(rows.hasNext()).isTrue();
			Literal count = (Literal) rows.next().getValue("count");
			assertThat(count.longValue())
					.as("the residual value-set filter must reject the compileTuple-only UNION child")
					.isEqualTo(1L);
			assertThat(rows.hasNext()).isFalse();
		}
	}

	@Test
	void unusedDeclaredLateralInputsDoNotConsumeNativeSlots() {
		MapBindingSet valuesRow = new MapBindingSet(60);
		Set<String> valueNames = new LinkedHashSet<>();
		for (int i = 0; i < 60; i++) {
			String name = "v" + i;
			valueNames.add(name);
			valuesRow.addBinding(name, VF.createLiteral(i));
		}
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(valueNames);
		values.setBindingSets(List.of(valuesRow));
		Set<String> unusedInputs = new LinkedHashSet<>();
		for (int i = 0; i < 20; i++) {
			unusedInputs.add("unused" + i);
		}
		Lateral lateral = new Lateral(values, new SingletonSet(), unusedInputs);
		SingleStatementSource source = new SingleStatementSource();
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null, null,
				0L, new EvaluationStatistics(), false);

		QueryEvaluationStep step = LmdbNativeAggregateCompiler.tryCompile(lateral,
				new QueryEvaluationContext.Minimal((Dataset) null), strategy, source);

		assertThat(step).as("only the sixty live VALUES names may occupy native slots").isNotNull();
		try (CloseableIteration<BindingSet> rows = step.evaluate(EmptyBindingSet.getInstance())) {
			assertThat(rows.hasNext()).isTrue();
			assertThat(rows.next().size()).isEqualTo(60);
			assertThat(rows.hasNext()).isFalse();
		}
	}

	private static BindingSetAssignment values(String name, Value value) {
		MapBindingSet row = new MapBindingSet(1);
		row.addBinding(name, value);
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of(name));
		assignment.setBindingSets(List.of(row));
		return assignment;
	}

	private static final class SingleStatementSource implements NativeLmdbQuerySource {
		private static final Map<Value, Long> IDS = Map.of(
				SUBJECT, SUBJECT_ID,
				LINK, LINK_ID,
				NAME_1, NAME_1_ID,
				NAME_2, NAME_2_ID);
		private static final Map<Long, Value> VALUES = Map.of(
				SUBJECT_ID, SUBJECT,
				LINK_ID, LINK,
				NAME_1_ID, NAME_1,
				NAME_2_ID, NAME_2);

		@Override
		public long idOf(Value value) {
			return IDS.getOrDefault(value, UNKNOWN_ID);
		}

		@Override
		public Value lazyValue(long id) {
			return VALUES.get(id);
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public RecordIterator statements(long subj, long pred, long obj, long context) {
			return new SingleRecordIterator(matches(subj, pred, obj, context)
					? new long[] { SUBJECT_ID, LINK_ID, NAME_1_ID, 0L }
					: null);
		}

		@Override
		public long count(long subj, long pred, long obj, long context) {
			return matches(subj, pred, obj, context) ? 1L : 0L;
		}

		@Override
		public boolean has(long subj, long pred, long obj, long context) {
			return matches(subj, pred, obj, context);
		}

		@Override
		public double estimate(long subj, long pred, long obj, long context) {
			return matches(subj, pred, obj, context) ? 1D : 0D;
		}

		@Override
		public boolean hasStatementsInSource() {
			return true;
		}

		private static boolean matches(long subj, long pred, long obj, long context) {
			return matchesField(subj, SUBJECT_ID) && matchesField(pred, LINK_ID)
					&& matchesField(obj, NAME_1_ID) && matchesField(context, 0L);
		}

		private static boolean matchesField(long requested, long actual) {
			return requested == UNKNOWN_ID || requested == actual;
		}
	}

	private static final class SingleRecordIterator implements RecordIterator {
		private long[] record;

		private SingleRecordIterator(long[] record) {
			this.record = record;
		}

		@Override
		public long[] next() {
			long[] next = record;
			record = null;
			return next;
		}

		@Override
		public void close() {
			record = null;
		}
	}

	private static final class EmptyTripleSource implements TripleSource {

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return EMPTY_ITERATION;
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}
	}
